function checkEqualTree(root) {
  const seen = new Set();

  function subtreeSum(node) {
    if (!node) {
      return 0;
    }
    const sum = node.val + subtreeSum(node.left) + subtreeSum(node.right);
    if (node !== root) {
      seen.add(sum);
    }
    return sum;
  }

  const total = subtreeSum(root);
  if (total % 2 !== 0) {
    return false;
  }
  return seen.has(total / 2);
}

