  // Try cutting above every non-root node and add up both halves from scratch.
  const nodes = [];
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    nodes.push(node);
    if (node.left) stack.push(node.left);
    if (node.right) stack.push(node.right);
  }
  const add = (start, skip) => {
    let total = 0;
    const pending = [start];
    while (pending.length) {
      const node = pending.pop();
      if (!node || node === skip) continue;
      total += node.val;
      pending.push(node.left, node.right);
    }
    return total;
  };
  for (const cut of nodes) {
    if (cut === root) continue;
    if (add(cut, null) === add(root, cut)) return true;
  }
  return false;
}

