function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const LIMIT = 100000;
  const count = size === 'large' ? 900 + pick(100) : 1 + pick(10);
  const span = size === 'large' ? (rand() < 0.5 ? LIMIT : 50) : (rand() < 0.2 ? LIMIT : 3);
  const value = () => pick(2 * span + 1) - span;
  const deep = rand() < 0.3;
  const nodes = [{ val: value(), left: null, right: null, parent: null }];
  while (nodes.length < count) {
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    const node = { val: value(), left: null, right: null, parent };
    parent[side] = node;
    nodes.push(node);
  }
  // Half the time, shift values outside one chosen subtree so that cutting above it splits the sum evenly.
  if (count > 1 && rand() < 0.5) {
    const cut = nodes[1 + pick(count - 1)];
    const inside = new Set();
    const pending = [cut];
    while (pending.length) {
      const node = pending.pop();
      if (!node) continue;
      inside.add(node);
      pending.push(node.left, node.right);
    }
    let part = 0;
    for (const node of inside) part += node.val;
    let total = 0;
    for (const node of nodes) total += node.val;
    let delta = 2 * part - total;
    for (const node of nodes) {
      if (delta === 0) break;
      if (inside.has(node)) continue;
      const shift = Math.max(-LIMIT - node.val, Math.min(LIMIT - node.val, delta));
      node.val += shift;
      delta -= shift;
    }
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
